					if bleeding then
						wounds = wounds + bleeding.stacks 
					end
					panicroll = panicroll - 10*wounds
												
					if wounds > 1 then
						local panicshance = 100-health_perc
					end
					
					if will_perc < 40 then
						local panicshance = Max(panicshance,100-will_perc)
