	PlaceObj('ModItemFolder', {
		'name', "Perks",
	}, {
		PlaceObj('ModItemCombatAction', {
			ActionCamera = true,
			ActionType = "Ranged Attack",
			AimType = "mobile",
			CostBasedOnWeapon = true,
			Description = T(954601292221, --[[ModItemCombatAction VengefulTemperament1 Description]] "<em>Once per turn</em>.\nMove to a new location and then shoot the closest enemy."),
			DisplayName = T(749486825928, --[[ModItemCombatAction VengefulTemperament1 DisplayName]] 'Ураган "Норма"'),
			FiringModeMember = "Attack",
			GetActionDamage = function (self, unit, target, args)
				local rangedAttack = unit:GetDefaultAttackAction("ranged")
				return rangedAttack:GetActionDamage(unit, target, args)
			end,
			GetActionDescription = function (self, units)
				local description = self.Description
				local unit = units and units[1]
				if not unit then
					return self:GetActionDisplayName()
				end
				
				local damage, base, bonus = self:GetActionDamage(unit)
				return T{description, damage = damage, basedamage = base, bonusdamage = bonus}
			end,
			GetActionResults = function (self, unit, args)
				return GetMobileShotResults(self, unit, args)
			end,
			GetAimParams = function (self, unit, weapon)
				if self.AimType == "cone" then
					return weapon:GetAreaAttackParams(self.id, unit)
				elseif self.AimType == "mobile" then
					local shots = self:ResolveValue("mobile_num_shots") or 5
					local move_ap = self:ResolveValue("mobile_move_ap")
					assert(move_ap)
					return { num_shots = shots, move_ap = move_ap * const.Scale.AP}
				elseif self.AimType == "parabola aoe" or self.AimType == "line aoe" then	
					return weapon.AreaOfEffect
				end
				
				return 0
			end,
			GetAnyTarget = function (self, units)
				return self:GetTargets(units)[1]
			end,
			GetAttackWeapons = function (self, unit, args)
				if args and args.weapon then return args.weapon end
				local weapon = unit:GetActiveWeapons("Firearm")
				return weapon -- make sure to return only 1 weapon, the attack doesn't use 2
			end,
			GetTargets = function (self, units)
				local unit = units[1]
				if unit then	
					return GetEnemies(unit)
				end
				return {}
			end,
			GetUIState = function (self, units, args)
				if not g_Combat then
					return "disabled", AttackDisableReasons.CombatOnly
				end
				return CombatActionGenericAttackGetUIState(self, units, args)
			end,
			Icon = "UI/Icons/Perks/VengefulTemperament",
			IdDefault = "VengefulTemperament1default",
			IsAimableAttack = false,
			KeybindingSortId = "2371",
			MultiSelectBehavior = "first",
			Parameters = {
				PlaceObj('PresetParamNumber', {
					'Name', "mobile_move_ap",
					'Value', 10,
					'Tag', "<mobile_move_ap>",
				}),
				PlaceObj('PresetParamNumber', {
					'Name', "cooldown",
					'Tag', "<cooldown>",
				}),
			},
			RequireState = "any",
			RequireWeapon = true,
			Run = function (self, unit, ap, ...)
				unit:SetActionCommand("RunAndGun", self.id, ap, ...)
			end,
			ShowIn = "SignatureAbilities",
			SortKey = 2,
			UIBegin = function (self, units, args)
				CombatActionAttackStart(self, units, args, "IModeCombatMovingAttack")
			end,
			group = "SignatureAbilities",
			id = "VengefulTemperament1",
		}),
		PlaceObj('ModItemCharacterEffectCompositeDef', {
			'Group', "Perk-Personal",
			'Id', "TheGrim",
			'Parameters', {
				PlaceObj('PresetParamNumber', {
					'Name', "fearAoE",
					'Value', 10,
					'Tag', "<fearAoE>",
				}),
			},
			'object_class', "Perk",
			'unit_reactions', {
				PlaceObj('UnitReaction', {
					Event = "OnUnitAttack",
					Handler = function (self, target, attacker, action, attack_target, results, attack_args)
						if target == attacker and action.id == self.class and IsKindOf(attack_target, "Unit") and table.find(results.killed_units or empty_table, attack_target) then
							for _, unit in ipairs(g_Units) do
								if unit ~= attack_target and unit.team:IsAllySide(attack_target.team) and DivRound(unit:GetDist(attack_target), const.SlabSizeX) <= self:ResolveValue("fearAoE") then
									unit:AddStatusEffect("Panicked")
									unit.ActionPoints = unit:GetMaxActionPoints()
								end
							end
						end
					end,
					param_bindings = false,
				}),
				PlaceObj('UnitReaction', {
					Event = "OnCalcCritChance",
					Handler = function (self, target, attacker, attack_target, action, weapon, data)
						if target == attacker and data.action_id == self.class then
							data.guaranteed_crit = true
						end
					end,
					param_bindings = false,
				}),
			},
			'DisplayName', T(623795138668, --[[ModItemCharacterEffectCompositeDef TheGrim DisplayName]] "Мрачная судьба"),
			'Description', T(773536167600, --[[ModItemCharacterEffectCompositeDef TheGrim Description]] "<em>Дистанционная атака</em> автоматически вызывающая <GameTerm('Crit')>.\n\nКогда атакующий убивает цель, остальные враги вокруг впадают в <GameTerm('Panic')>.\n\nНе может быть использовано с дробовиками."),
			'Icon', "UI/Icons/Perks/TheGrim",
